INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind manuelle Tests immer langsamer als automatisierte?', 2, '[{"text": "Ja", "correct": true, "because": "Menschliche Ausführung dauert länger"}, {"text": "Nein", "correct": false, "because": "Selten schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für wiederholbare Tests?', 3, '[{"text": "Automatisiert", "correct": true, "because": "Schnell und konsistent"}, {"text": "Manuell", "correct": false, "because": "Zeitaufwendig und fehleranfällig"}, {"text": "Keine", "correct": false, "because": "Tests nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen automatisierte Tests für große Systeme nützlich?', 5, '[{"text": "Schnelligkeit", "correct": true, "because": "Viele Tests in kurzer Zeit"}, {"text": "Konsistenz", "correct": true, "because": "Keine menschlichen Fehler"}, {"text": "Geringer Aufwand", "correct": false, "because": "Setup kann komplex sein"}, {"text": "Einfache Anpassung", "correct": false, "because": "Skripte müssen geändert werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Manuelle Tests sind flexibler. b) Automatisierte Tests brauchen keine Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Planung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl einer Testmethode für eine Web-App?', 4, '[{"text": "Testabdeckung", "correct": false, "because": "Wichtig für Qualität"}, {"text": "Testdauer", "correct": false, "because": "Beeinflusst Zeitplan"}, {"text": "Farbanpassung der UI", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob manuelle Tests für explorative Tests besser sind?', 2, '[{"text": "Ja", "correct": true, "because": "Menschliche Intuition hilft"}, {"text": "Nein", "correct": false, "because": "Automatisierung weniger flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich für automatisierte Tests?', 3, '[{"text": "Wiederholbarkeit", "correct": true, "because": "Konsistente Ergebnisse"}, {"text": "Spontane Anpassung", "correct": false, "because": "Manuell besser"}, {"text": "Minimale Kosten", "correct": false, "because": "Setup kann teuer sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein manueller Test?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Schnelle Anpassung möglich"}, {"text": "Intuitive Fehlerfindung", "correct": true, "because": "Menschliche Einsicht"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Langsamer als automatisiert"}, {"text": "Kostensenkung", "correct": false, "because": "Arbeitsaufwand hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Automatisierte Tests sind fehlerfrei. b) Manuelle Tests sind subjektiv. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) ist falsch, Skripte können Fehler haben"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für automatisierte Tests?', 4, '[{"text": "Testskripte", "correct": false, "because": "Grundlage der Automatisierung"}, {"text": "Testframework", "correct": false, "because": "Strukturiert Tests"}, {"text": "Manuelle Eingriffe", "correct": true, "because": "Automatisierung vermeidet das"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind manuelle Tests für einmalige Tests geeignet?', 2, '[{"text": "Ja", "correct": true, "because": "Kein Skriptaufwand nötig"}, {"text": "Nein", "correct": false, "because": "Effizient für Einmaltests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für automatisierte Tests entscheidend?', 4, '[{"text": "Skriptqualität", "correct": true, "because": "Bestimmt Zuverlässigkeit"}, {"text": "Wiederholgenauigkeit", "correct": true, "because": "Konsistente Ergebnisse"}, {"text": "Spontane Änderungen", "correct": false, "because": "Manuell besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass automatisierte Tests keine Fehler übersehen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur so gut wie Skripte"}, {"text": "Ja", "correct": false, "because": "Fehler möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei manuellen Tests?', 3, '[{"text": "Flexibilität", "correct": true, "because": "Anpassung an neue Szenarien"}, {"text": "Schnelle Wiederholung", "correct": false, "because": "Automatisiert besser"}, {"text": "Geringer Aufwand", "correct": false, "because": "Zeitintensiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Automatisierte Tests sparen Zeit. b) Manuelle Tests sind immer ungenau.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, hängt von Tester ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein automatisierter Test?', 5, '[{"text": "Hoher Initialaufwand", "correct": true, "because": "Skripte erstellen"}, {"text": "Begrenzte Flexibilität", "correct": true, "because": "Nur vordefinierte Tests"}, {"text": "Geringere Kosten", "correct": false, "because": "Setup teuer"}, {"text": "Schnelle Anpassung", "correct": false, "because": "Manuell schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei manuellen Tests für eine Web-App unwichtig?', 3, '[{"text": "Nutzerinteraktion", "correct": false, "because": "Kern der Funktion"}, {"text": "Fehlererkennung", "correct": false, "because": "Hauptziel"}, {"text": "Automatische Wiederholung", "correct": true, "because": "Manuell nicht nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind automatisierte Tests für UI-Tests ideal?', 3, '[{"text": "Ja", "correct": true, "because": "Konsistent und schnell"}, {"text": "Nein", "correct": false, "because": "Manuell oft ergänzend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob manuelle Tests für komplexe Szenarien besser sind?', 2, '[{"text": "Ja", "correct": true, "because": "Menschliche Kreativität hilft"}, {"text": "Nein", "correct": false, "because": "Automatisierung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für Regressionstests?', 4, '[{"text": "Automatisiert", "correct": true, "because": "Schnell und wiederholbar"}, {"text": "Manuell", "correct": false, "because": "Zu zeitaufwendig"}, {"text": "Keine", "correct": false, "because": "Tests nötig"}]');
